class Solution {
    static const int MOD=1000000007;
    vector<vector<pair<int,int>>> graph;
    vector<long long> distance;
    vector<int> memo;
    int target;
    int dfs(int node){
        if(node==target)return 1;
        if(memo[node]>=0)return memo[node];
        long long ways=0;
        for(auto [next,weight]:graph[node])if(distance[next]<distance[node])ways+=dfs(next);
        return memo[node]=ways%MOD;
    }
    public:int countRestrictedPaths(int n,vector<vector<int>>& edges){
        target=n;
        graph.assign(n+1,{
        });
        for(auto& edge:edges){
            graph[edge[0]].push_back({
                edge[1],edge[2]
            });
            graph[edge[1]].push_back({
                edge[0],edge[2]
            });
        }
        distance.assign(n+1,LLONG_MAX);
        distance[n]=0;
        priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>> pending;
        pending.push({
            0,n
        });
        while(!pending.empty()){
            auto [cost,node]=pending.top();
            pending.pop();
            if(cost!=distance[node])continue;
            for(auto [next,weight]:graph[node])if(cost+weight<distance[next]){
                distance[next]=cost+weight;
                pending.push({
                    distance[next],next
                });
            }
        }
        memo.assign(n+1,-1);
        return dfs(1);
    }
};
